/// <summary>
/// X++ wrapper over the <c>AtomicAx.Zpl.Render</c> C# library (plan WP-1.1 / REQ-R-2).
/// Renders ZPL to one PNG per ^XA..^XZ label block, entirely in-process (no data egress, C-9).
/// </summary>
public final class AAXZplRenderService
{
    private const str DimensionsMissingExceptionType = 'AtomicAx.Zpl.Render.ZplDimensionsMissingException';
}

Method.Source:
/// <summary>
/// Renders ZPL to a list of PNG images (one container per ^XA..^XZ label block).
/// </summary>
/// <param name = "_zpl">The final, token-substituted ZPL.</param>
/// <param name = "_dpmm">Print density in dots/mm; 0 = use the configured fallback.</param>
/// <param name = "_widthMm">Label width in mm; 0 = parse ^PW from the ZPL, else fallback.</param>
/// <param name = "_heightMm">Label height in mm; 0 = parse ^LL from the ZPL, else fallback.</param>
/// <returns>A <c>List</c> of <c>Types::Container</c>, one PNG per label block.</returns>
/// <remarks>
/// REQ-R-2: dpmm is resolved to a non-zero value UP FRONT and passed on the FIRST render call,
/// so the C# renderer can parse the label's own ^PW/^LL when width/height are 0 (the label's
/// declared size WINS by default). When the caller supplies explicit width/height (the dialog's
/// size-override box), those override ^PW/^LL. Only when the label declares NO ^PW/^LL AND the
/// caller supplied no size does the renderer throw ZplDimensionsMissingException — caught here
/// and retried with the configured WHSParameters fallback (default 4x6 in). All other CLR errors
/// surface as a readable @AAXWarehouseTools:RenderFailed error (X++ owns fallback policy).
/// </remarks>
public static List renderToPngList(str _zpl, int _dpmm = 0, real _widthMm = 0, real _heightMm = 0)
{
    WHSParameters p = WHSParameters::find();

    // Resolve density UP FRONT so the FIRST call never trips the C# "dpmm <= 0" guard, which
    // would otherwise throw before ^PW/^LL is ever parsed (the original ordering bug). With
    // _widthMm/_heightMm == 0 the renderer parses the label's declared ^PW/^LL (label size wins);
    // with explicit dims it uses them (the form size-override case).
    int dpmm = _dpmm > 0 ? _dpmm : p.aaxPreviewDefaultDpmm();

    try
    {
        return AAXZplRenderService::renderOnce(_zpl, dpmm, _widthMm, _heightMm);
    }
    catch (Exception::CLRError)
    {
        System.Exception clrException = CLRInterop::getLastException();

        if (AAXZplRenderService::containsExceptionType(clrException, DimensionsMissingExceptionType))
        {
            // The label declares NO ^PW/^LL and the caller gave no size: re-invoke with the
            // configured WHSParameters fallbacks (default 4x6 in @ 8 dpmm). Explicit caller
            // dims (if any) still win over the fallback width/height.
            try
            {
                return AAXZplRenderService::renderOnce(
                    _zpl,
                    dpmm,
                    _widthMm > 0 ? _widthMm : p.aaxPreviewDefaultWidthMm(),
                    _heightMm > 0 ? _heightMm : p.aaxPreviewDefaultHeightMm());
            }
            catch (Exception::CLRError)
            {
                clrException = CLRInterop::getLastException();
                throw error(strFmt("@AAXWarehouseTools:RenderFailed",
                    AAXZplRenderService::innermostMessage(clrException)));
            }
        }

        throw error(strFmt("@AAXWarehouseTools:RenderFailed",
            AAXZplRenderService::innermostMessage(clrException)));
    }
}

/// <summary>
/// Single render pass; CLR exceptions bubble to the caller for policy handling.
/// </summary>
private static List renderOnce(str _zpl, int _dpmm, real _widthMm, real _heightMm)
{
    List pngList = new List(Types::Container);
    int  pngCount;
    int  i;

    // ZplRenderResult is the X++-friendly wrapper (Count / GetPng) — see DECISIONS.md (III.7):
    // X++ cannot declare closed generic CLR types such as IList<byte[]>.
    AtomicAx.Zpl.Render.ZplRenderResult renderResult =
        AtomicAx.Zpl.Render.ZplRenderService::RenderToPngs(_zpl, _dpmm, _widthMm, _heightMm);

    pngCount = renderResult.get_Count();

    for (i = 0; i < pngCount; i++)
    {
        pngList.addEnd(AAXZplRenderService::bytesToContainer(renderResult.GetPng(i)));
    }

    return pngList;
}

/// <summary>
/// Converts a CLR byte array to an X++ container (III.7).
/// </summary>
private static container bytesToContainer(System.Byte[] _bytes)
{
    System.IO.MemoryStream memoryStream = new System.IO.MemoryStream(_bytes);
    Binary binary = Binary::constructFromMemoryStream(memoryStream);
    return binary.getContainer();
}

/// <summary>
/// Rotates a PNG image clockwise by the given number of quarter turns (90 degrees each).
/// </summary>
/// <param name = "_png">The source PNG as an X++ <c>container</c>.</param>
/// <param name = "_quarterTurnsClockwise">
/// Quarter turns clockwise; taken modulo 4 by the renderer. 0 returns the input bytes unchanged.
/// </param>
/// <returns>The rotated PNG as an X++ <c>container</c>.</returns>
/// <remarks>
/// Thin wrapper over <c>AtomicAx.Zpl.Render.ZplRenderService::RotatePng(byte[], int)</c>
/// (integration contract). Mirrors the existing container&lt;-&gt;byte[] interop used by
/// <c>bytesToContainer</c> / <c>pngContainerToStream</c> (III.7): the container is
/// converted to a CLR byte[] via the same Binary/MemoryStream bridge, rotated in the
/// C# library, and the result is wrapped back into a container. CLR errors surface as a
/// readable RenderFailed error, consistent with <c>renderToPngList</c>.
/// </remarks>
public static container rotatePng(container _png, int _quarterTurnsClockwise)
{
    try
    {
        // container -> CLR byte[]: reuse the Binary/MemoryStream bridge already used by
        // pngContainerToStream; ToArray() yields the System.Byte[] the C# API expects.
        System.IO.MemoryStream sourceStream = AAXZplRenderService::pngContainerToStream(_png);
        System.Byte[] sourceBytes = sourceStream.ToArray();

        System.Byte[] rotatedBytes =
            AtomicAx.Zpl.Render.ZplRenderService::RotatePng(sourceBytes, _quarterTurnsClockwise);

        return AAXZplRenderService::bytesToContainer(rotatedBytes);
    }
    catch (Exception::CLRError)
    {
        System.Exception clrException = CLRInterop::getLastException();
        throw error(strFmt("@AAXWarehouseTools:RenderFailed",
            AAXZplRenderService::innermostMessage(clrException)));
    }
}

/// <summary>
/// Converts a PNG container back to a stream for the stream-only file APIs (F25/F27).
/// </summary>
public static System.IO.MemoryStream pngContainerToStream(container _png)
{
    Binary binary = Binary::constructFromContainer(_png);
    return binary.getMemoryStream();
}

/// <summary>
/// Walks the InnerException chain looking for a CLR exception of the given full type name.
/// </summary>
private static boolean containsExceptionType(System.Exception _exception, str _typeFullName)
{
    System.Exception current = _exception;

    while (current != null)
    {
        System.Type exceptionType = current.GetType();
        if (exceptionType.get_FullName() == _typeFullName)
        {
            return true;
        }
        current = current.get_InnerException();
    }

    return false;
}

/// <summary>
/// Returns the FULL CLR exception chain (outer to inner) for readable error reporting.
/// The outer ZplRenderException carries diagnostics (e.g. the native preloader probe log)
/// that an innermost-only message would hide (III.7 / U-1).
/// </summary>
private static str innermostMessage(System.Exception _exception)
{
    str result;
    System.Exception current = _exception;

    while (current != null)
    {
        result += (result ? '\n' : '') + current.get_Message();
        current = current.get_InnerException();
    }

    return result;
}
